const event = $input.first().json.event || $input.first().json;
const payload = event.payload || {};

const systemPrompt = `Eres el científico de validación y experimentación de RAX.\nTu misión es convertir suposiciones críticas en hipótesis comprobables y experimentos con criterios EX-ANTE.\nREGLAS FUNDAMENTALES:\n1. La hipótesis debe ser falsable (mínimo 25 caracteres, sin fórmulas vagas como 'a la gente le gustará').\n2. Define de antemano tanto el criterio de éxito (successCriterion) como el de refutación (rejectionCriterion).\n3. Propón un método concreto (entrevistas de problema, prueba de humo, concierge, prototipo de baja fidelidad).\n4. Salida en JSON estricto con: proposedHypotheses (array con statement, segment, whyItMatters, uncertainty, costOfBeingWrong, evaluationCriterion), proposedExperiment (objeto con question, method, metric, successCriterion, rejectionCriterion, durationDays, participants, evidencePlan), uncertainties (array).`;

const userPrompt = JSON.stringify({
  projectId: event.projectId,
  problem: payload.problem || '',
  assumptions: payload.assumptions || [],
  founderContext: payload.founderContext || {}
});

return [{
  json: {
    correlationId: event.correlationId || 'corr_' + Date.now(),
    callbackUrl: event.callback?.url || ($env.RAX_API_URL || 'https://rax-red.vercel.app') + '/api/n8n/callback',
    model: $env.OPENROUTER_MODEL || 'meta-llama/llama-3.3-70b-instruct:free',
    apiKey: $env.OPENROUTER_API_KEY || '',
    systemPrompt,
    userPrompt
  }
}];

const response = $input.first().json;
const prep = $('Build Experiment Design Prompt').first().json;

let parsed = {};
try {
  const content = response.choices?.[0]?.message?.content || '{}';
  parsed = JSON.parse(content);
} catch (e) {
  parsed = { proposedHypotheses: [], uncertainties: ['Salida JSON no válida'] };
}

const hypProposals = (parsed.proposedHypotheses || []).map(h => ({
  type: 'hypothesis',
  title: h.statement,
  description: `Segmento: ${h.segment} | Criterio: ${h.evaluationCriterion}`,
  needsHumanApproval: true,
  uncertainties: []
}));

const expProposal = parsed.proposedExperiment ? [{
  type: 'experiment',
  title: parsed.proposedExperiment.question,
  description: `Método: ${parsed.proposedExperiment.method} | Métrica: ${parsed.proposedExperiment.metric}`,
  successCriteria: `Éxito: ${parsed.proposedExperiment.successCriterion} | Refutación: ${parsed.proposedExperiment.rejectionCriterion}`,
  evidenceRequired: parsed.proposedExperiment.evidencePlan,
  needsHumanApproval: true,
  uncertainties: []
}] : [];

const callbackPayload = {
  operationId: 'op_exp_' + Date.now(),
  correlationId: prep.correlationId,
  workflowId: 'RAX-12',
  workflowVersion: '1.0.0',
  status: 'completed',
  usage: {
    model: response.model || prep.model,
    promptTokens: response.usage?.prompt_tokens || 0,
    completionTokens: response.usage?.completion_tokens || 0
  },
  data: {
    summary: `Se diseñaron ${hypProposals.length} hipótesis y ${expProposal.length} experimentos ex-ante.`,
    proposals: [...hypProposals, ...expProposal],
    uncertainties: parsed.uncertainties || []
  }
};

return [{
  json: {
    callbackUrl: prep.callbackUrl,
    payload: callbackPayload
  }
}];
